import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353;
    static final int MAX = 500;
    static long[] fac = new long[MAX + 1];
    static long[] finv = new long[MAX + 1];
    static long[] inv = new long[MAX + 1];
    static long[][] pow = new long[501][501];
    static long[][] dp = new long[501][501];

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        init();

        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int x = Integer.parseInt(st.nextToken());

        for (int i = 0; i < 501; i++) {
            pow[i][0] = 1;
            for (int j = 0; j < 500; j++) {
                pow[i][j + 1] = pow[i][j] * i % MOD;
            }
        }

        for (int i = 2; i <= n; i++) {
            int jj = Math.min(x, i - 1);
            for (int j = 1; j <= jj; j++) {
                dp[i][j] = (pow[j][i] - pow[j - 1][i]) % MOD;
                if (dp[i][j] < 0) dp[i][j] += MOD;
            }
        }

        for (int i = 2; i <= n; i++) {
            for (int j = 1; j <= x; j++) {
                if (dp[i][j] == 0) continue;
                for (int k = 0; k <= n - i; k++) {
                    int nj = j + i + k - 1;
                    if (nj > x) break;
                    long comb = modCombination(i + k, k);
                    long term = dp[i][j] * pow[i + k - 1][k] % MOD * comb % MOD;
                    dp[i + k][nj] = (dp[i + k][nj] + term) % MOD;
                }
            }
        }

        long ans = 0;
        for (int j = 1; j <= x; j++) {
            ans = (ans + dp[n][j]) % MOD;
        }
        ans = (ans % MOD + MOD) % MOD;
        pw.println(ans);
        pw.flush();
    }

    static void init() {
        fac[0] = 1; fac[1] = 1;
        finv[0] = 1; finv[1] = 1;
        inv[1] = 1;
        for (int i = 2; i <= MAX; i++) {
            fac[i] = fac[i - 1] * i % MOD;
            inv[i] = MOD - inv[(int)(MOD % i)] * (MOD / i) % MOD;
            finv[i] = finv[i - 1] * inv[i] % MOD;
        }
    }

    static long modCombination(int n, int k) {
        if (n < k) return 0;
        long ret = 1;
        while (n > 0 || k > 0) {
            int ni = n % (int)MOD;
            int ki = k % (int)MOD;
            if (ni < ki) return 0;
            ret = ret * fac[ni] % MOD * finv[ki] % MOD * finv[ni - ki] % MOD;
            n /= MOD;
            k /= MOD;
        }
        return ret;
    }
}

